package com.familyguard.child;
import android.app.Notification;import android.app.NotificationChannel;import android.app.NotificationManager;import android.app.Service;import android.content.Context;import android.content.Intent;import android.location.Location;import android.location.LocationListener;import android.location.LocationManager;import android.os.Build;import android.os.Bundle;import android.os.IBinder;
import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.firestore.FirebaseFirestore;import com.google.firebase.firestore.FieldValue;import com.google.firebase.firestore.ListenerRegistration;import com.google.firebase.firestore.Query;import com.google.firebase.firestore.DocumentSnapshot;import java.util.*;
public class LocationSessionService extends Service implements LocationListener{
 private static final String CHANNEL="familyguard_location";private LocationManager manager;private ListenerRegistration fenceListener;private List<DocumentSnapshot> fences=new ArrayList<>();
 @Override public void onCreate(){super.onCreate();createChannel();Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);Notification n=builder.setContentTitle("FamilyGuard location sharing").setContentText("Location sharing and enabled geofence alerts are active and visible.").setSmallIcon(android.R.drawable.ic_menu_mylocation).setOngoing(true).build();startForeground(7,n);manager=(LocationManager)getSystemService(Context.LOCATION_SERVICE);String child=FirebaseAuth.getInstance().getUid();if(child!=null)fenceListener=FirebaseFirestore.getInstance().collection("geofences").whereEqualTo("childUid",child).whereEqualTo("active",true).addSnapshotListener((snap,e)->{if(e==null&&snap!=null){fences=new ArrayList<>(snap.getDocuments());}});boolean listening=false;if(manager!=null){for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER}){try{if(manager.getAllProviders().contains(provider)&&manager.isProviderEnabled(provider)){manager.requestLocationUpdates(provider,30000L,provider.equals(LocationManager.GPS_PROVIDER)?10f:25f,this);listening=true;}}catch(SecurityException|IllegalArgumentException ignored){}}}if(!listening)stopSelf();}
 private void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL,"Location sharing",NotificationManager.IMPORTANCE_LOW);NotificationManager nm=getSystemService(NotificationManager.class);if(nm!=null)nm.createNotificationChannel(c);}}
 @Override public void onLocationChanged(Location l){String child=FirebaseAuth.getInstance().getUid();String parent=getSharedPreferences("familyguard_child",MODE_PRIVATE).getString("parent_uid",null);if(child==null||parent==null)return;Map<String,Object>d=new HashMap<>();d.put("childUid",child);d.put("parentUid",parent);d.put("latitude",l.getLatitude());d.put("longitude",l.getLongitude());d.put("accuracyMeters",l.getAccuracy());d.put("capturedAt",FieldValue.serverTimestamp());FirebaseFirestore db=FirebaseFirestore.getInstance();db.collection("locations").document(child).set(d);Map<String,Object>h=new HashMap<>(d);h.put("deviceTime",l.getTime());db.collection("locationHistory").add(h);getSharedPreferences("familyguard_child",MODE_PRIVATE).edit().putLong("last_location_time",l.getTime()).putString("last_latitude",String.valueOf(l.getLatitude())).putString("last_longitude",String.valueOf(l.getLongitude())).apply();checkGeofences(l,child,parent,db);}
 private void checkGeofences(Location current,String child,String parent,FirebaseFirestore db){android.content.SharedPreferences prefs=getSharedPreferences("familyguard_geofences",MODE_PRIVATE);for(DocumentSnapshot fence:fences){Double lat=fence.getDouble("latitude"),lon=fence.getDouble("longitude"),radius=fence.getDouble("radiusMeters");if(lat==null||lon==null||radius==null||radius<=0)continue;float[] dist=new float[1];Location.distanceBetween(current.getLatitude(),current.getLongitude(),lat,lon,dist);boolean inside=dist[0]<=radius;String key=fence.getId();String prior=prefs.getString(key,null);String now=inside?"inside":"outside";if(prior==null){prefs.edit().putString(key,now).apply();continue;}if(!prior.equals(now)){prefs.edit().putString(key,now).apply();Map<String,Object> event=new HashMap<>();event.put("childUid",child);event.put("parentUid",parent);event.put("geofenceId",key);event.put("label",fence.getString("label")==null?"Safe zone":fence.getString("label"));event.put("eventType",inside?"entered":"exited");event.put("latitude",current.getLatitude());event.put("longitude",current.getLongitude());event.put("deviceTime",current.getTime());event.put("createdAt",FieldValue.serverTimestamp());db.collection("geofenceEvents").add(event);}}}
 @Override public int onStartCommand(Intent i,int f,int id){return START_STICKY;}
 @Override public void onDestroy(){if(manager!=null)manager.removeUpdates(this);if(fenceListener!=null)fenceListener.remove();super.onDestroy();}
 @Override public void onProviderEnabled(String p){}@Override public void onProviderDisabled(String p){}@Override public void onStatusChanged(String p,int s,Bundle b){}@Override public IBinder onBind(Intent i){return null;}
}